/* Signature Zulu Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Thandolwethu": "From thanda (love) + -lwethu (our): 'our beloved'.", "Jabulisile": "From jabula (rejoice) + -isile: 'she has brought joy'.", "Mvulazana": "From mvula (rain) + -azana: 'little rain'.", "Mandlakazi": "From mandla (strength) + -kazi: 'great strength'.", "Hlanhlakahle": "From inhlanhla (luck) + kahle (well): 'good luck'.", "Thokozile": "From thokoza (be happy).", "Thandizwe": "From thanda + izwe (land): Signature clan-style surname.", "Jabulani-khaya": "Signature clan-style surname: 'joy home'.", "Mvulabantu": "From mvula + bantu (people): Signature surname.", "Hlanhlabani": "Signature clan-style surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Thandolwethu';
console.log(lookup(q));

